28	export function locationSpecToMetadataName(location: LocationSpec) {
29	  const hash = createHash('sha1')
30	    .update(`${location.type}:${location.target}`)
31	    .digest('hex');
32	  return `generated-${hash}`;
33	}
34	
35	export function locationSpecToLocationEntity(opts: {
36	  location: LocationSpec;
37	  parentEntity?: Entity;
38	}): LocationEntityV1alpha1 {
39	  const location = opts.location;
40	  const parentEntity = opts.parentEntity;
41	
42	  let ownLocation: string;
43	  let originLocation: string;
44	  if (parentEntity) {
45	    const maybeOwnLocation =
46	      parentEntity.metadata.annotations?.[ANNOTATION_LOCATION];
47	    if (!maybeOwnLocation) {
48	      throw new Error(
49	        `Parent entity '${stringifyEntityRef(
50	          parentEntity,
51	        )}' of location '${stringifyLocationRef(
52	          location,
53	        )}' does not have a location annotation`,
54	      );
55	    }
56	    ownLocation = maybeOwnLocation;
57	    const maybeOriginLocation =
58	      parentEntity.metadata.annotations?.[ANNOTATION_ORIGIN_LOCATION];
59	    if (!maybeOriginLocation) {
60	      throw new Error(
61	        `Parent entity '${stringifyEntityRef(
62	          parentEntity,
63	        )}' of location '${stringifyLocationRef(
64	          location,
65	        )}' does not have an origin location annotation`,
66	      );
67	    }
68	    originLocation = maybeOriginLocation;
69	  } else {
70	    ownLocation = stringifyLocationRef(location);
71	    originLocation = ownLocation;
72	  }
73	
74	  const result: LocationEntityV1alpha1 = {
75	    apiVersion: 'backstage.io/v1alpha1',
76	    kind: 'Location',
77	    metadata: {
78	      name: locationSpecToMetadataName(location),
79	      annotations: {
80	        [ANNOTATION_LOCATION]: ownLocation,
81	        [ANNOTATION_ORIGIN_LOCATION]: originLocation,
82	      },
83	    },
84	    spec: {
85	      type: location.type,
86	      target: location.target,
87	      presence: location.presence,
88	    },
89	  };
90	
91	  return result;
92	}
