32	/**
33	 * Represents the refresh_state table.
34	 *
35	 * @remarks
36	 *
37	 * Every unique entity ref emitted by a provider or a parent entity becomes a
38	 * row in this table, even before processing has started on it. The actual final
39	 * data, after processing and stitching completes, is instead in the
40	 * final_entities table.
41	 *
42	 * Datetime columns are both string and Date, because different database engines
43	 * return them in different forms on the client side.
44	 */
45	export type DbRefreshStateRow = {
46	  /**
47	   * The unique ID of the entity. This is different to the entity ref, in that
48	   * it gets regenerated randomly each time a row is added to the table, no
49	   * matter what the original entity data was.
50	   */
51	  entity_id: string;
52	  /**
53	   * The entity string ref (on lowercase kind:namespace/name form)
54	   */
55	  entity_ref: string;
56	  /**
57	   * The JSON of the raw entity, as it was received from the entity provider.
58	   */
59	  unprocessed_entity: string;
60	  /**
61	   * A stable hash of the unprocessed entity, used to detect changed/unchanged
62	   * data for a given entity over time.
63	   */
64	  unprocessed_hash?: string;
65	  /**
66	   * The JSON of the processed entity (if processing has run yet on it).
67	   */
68	  processed_entity?: string;
69	  /**
70	   * A stable hash of the processed entity AND all other emitted things during
71	   * processing, such as relations.
72	   */
73	  result_hash?: string;
74	  /**
75	   * Per-entity cached data on JSON form. This is read and written by processors
76	   * who wish to leverage this feature.
77	   */
78	  cache?: string;
79	  /**
80	   * The next point in time that this entity is due for processing. This
81	   * continuously gets moved forward as items are picked up for processing.
82	   */
83	  next_update_at: string | Date;
84	  /**
85	   * The last time that this entity was emitted by somebody (the entity provider
86	   * or a parent entity).
87	   *
88	   * @remarks
89	   *
90	   * Don't rely on this column more than at most as being loosely informative.
91	   * Its semantics aren't fully settled yet.
92	   */
93	  last_discovery_at: string | Date;
94	  /**
95	   * A JSON serialized array of errors (if any) encountered during processing.
96	   */
97	  errors?: string;
98	  /**
99	   * A conflict detection/resolution key for the entity.
100	   *
101	   * @remarks
102	   *
103	   * The exact value semantics differs, but may for example be a URL pointing to
104	   * where the entity was sourced from. If a "competing" provider or parent
105	   * entity tries to emit an entity that has the same entity ref but a different
106	   * location key, a conflict is detected (you aren't allowed to "trample" over
107	   * a previously existing entity).
108	   *
109	   * Some providers may choose to emit entities with no location key set at all.
110	   * This is a signal that it's only loosely claimed, and that any other
111	   * competing provider/parent is allowed to overwrite and claim it as theirs
112	   * instead.
113	   */
114	  location_key?: string;
115	};
