143	/**
144	 * Represents the stitch_queue table.
145	 *
146	 * @remarks
147	 *
148	 * Each row represents a pending stitch request for an entity. When a stitch
149	 * completes successfully and the ticket hasn't changed, the row is deleted.
150	 */
151	export type DbStitchQueueRow = {
152	  /**
153	   * The entity ref that needs stitching (primary key).
154	   */
155	  entity_ref: string;
156	  /**
157	   * A random value that changes with every new stitch request. Used for
158	   * optimistic concurrency: when a stitch completes, the row is only deleted
159	   * if this ticket still matches (meaning no new request came in while
160	   * stitching was in progress).
161	   */
162	  stitch_ticket: string;
163	  /**
164	   * The point in time when this entity should next be stitched.
165	   *
166	   * @remarks
167	   *
168	   * Each time that a request is made, this timestamp is updated to the current
169	   * time, overwriting the previous value if applicable.
170	   *
171	   * When the stitch loop runs and picks up an entity, this timestamp is not
172	   * immediately reset. It's instead moved forward in time by a certain amount,
173	   * which means that if the stitcher for some reason fails (eg if the process
174	   * crashes or gets shut down), the entity will be picked up again in the
175	   * future.
176	   *
177	   * Only when a stitch run is completed successfully, AND it's found that the
178	   * stitch ticket has not changed since the start (which means that no new
179	   * request has been made behind our backs), does the row get deleted.
180	   */
181	  next_stitch_at: string | Date;
182	};
183	
184	export type DbSearchRow = {
185	  entity_id: string;
186	  key: string;
187	  original_value: string | null;
188	  value: string | null;
189	};
