17	import { Location } from '@backstage/catalog-client';
18	import { ConflictError, InputError, NotFoundError } from '@backstage/errors';
19	import { Knex } from 'knex';
20	import { v4 as uuid } from 'uuid';
21	import {
22	  DbLocationsRow,
23	  DbRefreshStateRow,
24	  DbSearchRow,
25	} from '../database/tables';
26	import { getEntityLocationRef } from '../processing/util';
27	import {
28	  EntityProvider,
29	  EntityProviderConnection,
30	} from '@backstage/plugin-catalog-node';
31	import { locationSpecToLocationEntity } from '../util/conversion';
32	import { LocationInput, LocationStore } from '../service/types';
33	import {
34	  ANNOTATION_ORIGIN_LOCATION,
35	  CompoundEntityRef,
