42	} from '@backstage/plugin-catalog-node/alpha';
43	import { chunk, uniqBy } from 'lodash';
44	import parseGitUrl, { type GitUrl } from 'git-url-parse';
45	import { ScmEventHandlingConfig } from '../util/readScmEventHandlingConfig';
