51	export class DefaultLocationStore implements LocationStore, EntityProvider {
52	  private _connection: EntityProviderConnection | undefined;
53	  private readonly db: Knex;
54	  private readonly scmEvents: CatalogScmEventsService;
55	  private readonly scmEventHandlingConfig: ScmEventHandlingConfig;
56	
57	  constructor(
58	    db: Knex,
59	    scmEvents: CatalogScmEventsService,
60	    scmEventHandlingConfig: ScmEventHandlingConfig,
61	  ) {
62	    this.db = db;
63	    this.scmEvents = scmEvents;
64	    this.scmEventHandlingConfig = scmEventHandlingConfig;
65	  }
66	
67	  getProviderName(): string {
68	    return 'DefaultLocationStore';
69	  }
70	
71	  async createLocation(
72	    input: LocationInput,
73	    options?: {
74	      onConflict?: 'refresh' | 'reject';
75	    },
76	  ): Promise<Location> {
77	    let existed = false;
78	
79	    const location = await this.db.transaction(async tx => {
80	      // Attempt to find a previous location matching the input
81	      const previousLocations = await this.locations(tx);
82	      // TODO: when location id's are a compilation of input target we can remove this full
83	      // lookup of locations first and just grab the by that instead.
84	      const previousLocation = previousLocations.find(
85	        l => input.type === l.type && input.target === l.target,
86	      );
87	      if (previousLocation) {
88	        if (options?.onConflict === 'refresh') {
89	          existed = true;
90	          return previousLocation;
91	        }
92	        throw new ConflictError(
93	          `Location ${input.type}:${input.target} already exists`,
94	        );
95	      }
96	
97	      const inner: DbLocationsRow = {
98	        id: uuid(),
99	        type: input.type,
100	        target: input.target,
101	      };
102	
103	      await tx<DbLocationsRow>('locations').insert(inner);
104	
105	      return inner;
106	    });
107	
108	    // Always upsert the entity, even if the location already existed, to
109	    // recover from cases where the entity was inadvertently deleted.
110	    const entity = locationSpecToLocationEntity({ location });
111	    await this.connection.applyMutation({
112	      type: 'delta',
113	      added: [{ entity, locationKey: getEntityLocationRef(entity) }],
114	      removed: [],
115	    });
116	
117	    if (existed) {
118	      // This is the "onConflict refresh" case, where a re-registration safely
119	      // tries to recover from a bad state.
120	      const entityRef = stringifyEntityRef(entity);
121	      await this.db<DbRefreshStateRow>('refresh_state')
122	        .where({ entity_ref: entityRef })
123	        .update({
124	          next_update_at: this.db.fn.now(),
125	          result_hash: '',
126	        });
127	    }
128	
129	    return location;
130	  }
131	
132	  async listLocations(): Promise<Location[]> {
133	    return await this.locations();
134	  }
135	
136	  async queryLocations(options: {
137	    limit: number;
138	    afterId?: string;
139	    query?: FilterPredicate;
140	  }): Promise<{ items: Location[]; totalItems: number }> {
141	    let itemsQuery = this.db<DbLocationsRow>('locations').whereNot(
142	      'type',
143	      'bootstrap',
144	    );
145	
146	    if (options.query) {
147	      itemsQuery = applyLocationFilterToQuery(
148	        this.db.client.config.client,
149	        itemsQuery,
150	        options.query,
151	      );
152	    }
153	
154	    const countQuery = itemsQuery.clone().count('*', { as: 'count' });
155	
156	    itemsQuery = itemsQuery.orderBy('id', 'asc');
157	    if (options.afterId !== undefined) {
158	      itemsQuery = itemsQuery.where('id', '>', options.afterId);
159	    }
160	    if (options.limit !== undefined) {
161	      itemsQuery = itemsQuery.limit(options.limit);
162	    }
163	
164	    const [items, [{ count }]] = await Promise.all([itemsQuery, countQuery]);
165	
166	    return {
167	      items: items.map(item => ({
168	        id: item.id,
169	        target: item.target,
170	        type: item.type,
171	      })),
172	      totalItems: Number(count),
173	    };
174	  }
175	
176	  async getLocation(id: string): Promise<Location> {
177	    const items = await this.db<DbLocationsRow>('locations')
178	      .where({ id })
179	      .select();
180	
181	    if (!items.length) {
182	      throw new NotFoundError(`Found no location with ID ${id}`);
183	    }
184	    return items[0];
185	  }
186	
187	  async deleteLocation(id: string): Promise<void> {
188	    if (!this.connection) {
189	      throw new Error('location store is not initialized');
190	    }
191	
192	    const deleted = await this.db.transaction(async tx => {
193	      const [location] = await tx<DbLocationsRow>('locations')
194	        .where({ id })
195	        .select();
196	
197	      if (!location) {
198	        throw new NotFoundError(`Found no location with ID ${id}`);
199	      }
200	
201	      await tx<DbLocationsRow>('locations').where({ id }).del();
202	      return location;
203	    });
204	    const entity = locationSpecToLocationEntity({ location: deleted });
205	    await this.connection.applyMutation({
206	      type: 'delta',
207	      added: [],
208	      removed: [{ entity, locationKey: getEntityLocationRef(entity) }],
209	    });
210	  }
211	
212	  async getLocationByEntity(entityRef: CompoundEntityRef): Promise<Location> {
213	    const entityRefString = stringifyEntityRef(entityRef);
214	
215	    const [entityRow] = await this.db<DbRefreshStateRow>('refresh_state')
216	      .where({ entity_ref: entityRefString })
217	      .select('entity_id')
218	      .limit(1);
219	    if (!entityRow) {
220	      throw new NotFoundError(`found no entity for ref ${entityRefString}`);
221	    }
222	
223	    const [searchRow] = await this.db<DbSearchRow>('search')
224	      .where({
225	        entity_id: entityRow.entity_id,
226	        key: `metadata.annotations.${ANNOTATION_ORIGIN_LOCATION}`,
227	      })
228	      .select('original_value')
